sect1.para:
   Directories र files जस्तै, PHP namespaces मा पनि namespace नामहरूको तहगत संरचना
   (hierarchy) निर्दिष्ट गर्न सकिने सुविधा हुन्छ। त्यसैले, namespace को नामलाई sub-levels
   सहित परिभाषित गर्न सकिन्छ:

    तहगत संरचना (hierarchy) सहितको एउटा namespace घोषणा गर्ने उदाहरण


<?php
namespace MyProject\Sub\Level;

const CONNECT_OK = 1;
class Connection { /* ... */ }
function connect() { /* ... */  }



   माथिको उदाहरणले constant MyProject\Sub\Level\CONNECT_OK,
   class MyProject\Sub\Level\Connection र function
   MyProject\Sub\Level\connect सिर्जना गर्छ।

   Global non-namespaced code लाई namespaced code सँगै राख्नका लागि bracketed syntax मात्र
   समर्थित छ। Global code लाई बिना कुनै नामको namespace statement भित्र यसरी राख्नुपर्छ:

    धेरै namespaces र unnamespaced code घोषणा गर्ने उदाहरण


<?php
namespace MyProject {

const CONNECT_OK = 1;
class Connection {
    public static function start() {
        print __METHOD__ . "\n";
    }
}

function connect() {
    print __FUNCTION__ . "\n";
}
}

namespace { // global code
print strlen("hi") . "\n";
MyProject\connect();
MyProject\Connection::start();
}

   सुरुमा आउने declare statement बाहेक अन्य कुनै पनि PHP code namespace brackets भन्दा
   बाहिर रहन पाउँदैन।

    धेरै namespaces र unnamespaced code घोषणा गर्ने उदाहरण


<?php
declare(strict_types=1);
namespace MyProject {

const CONNECT_OK = 1;
class Connection {
    public static function start() {
        print __METHOD__ . "\n";
    }
}

function connect() {
    print __FUNCTION__ . "\n";
}
}

namespace { // global code
print strlen("hi") . "\n";
MyProject\connect();
MyProject\Connection::start();
}

   यहाँ वास्तविक code मा यी तीन प्रकारका syntax को उदाहरण दिइएको छ:

    file1.php


<?php
namespace Foo\Bar\subnamespace;

const FOO = 1;
function foo() {}
class foo
{
    static function staticmethod() {}
}


    file2.php


<?php
namespace Foo\Bar;
include 'file1.php';

const FOO = 2;
function foo() {}
class foo
{
    static function staticmethod() {}
}

/* Unqualified name */
foo(); // function Foo\Bar\foo मा resolve हुन्छ
foo::staticmethod(); // class Foo\Bar\foo, method staticmethod मा resolve हुन्छ
echo FOO; // constant Foo\Bar\FOO मा resolve हुन्छ

/* Qualified name */
subnamespace\foo(); // function Foo\Bar\subnamespace\foo मा resolve हुन्छ
subnamespace\foo::staticmethod(); // class Foo\Bar\subnamespace\foo,
                                  // method staticmethod मा resolve हुन्छ
echo subnamespace\FOO; // constant Foo\Bar\subnamespace\FOO मा resolve हुन्छ

/* Fully qualified name */
\Foo\Bar\foo(); // function Foo\Bar\foo मा resolve हुन्छ
\Foo\Bar\foo::staticmethod(); // class Foo\Bar\foo, method staticmethod मा resolve हुन्छ
echo \Foo\Bar\FOO; // constant Foo\Bar\FOO मा resolve हुन्छ

   ध्यान दिनुहोस्, कुनै पनि global class, function वा constant पहुँच गर्नका लागि
   \strlen, \Exception वा
   \INI_ALL जस्ता fully qualified name प्रयोग गर्न सकिन्छ।

    Namespace भित्रबाट global classes, functions र constants पहुँच गर्ने उदाहरण


<?php
namespace Foo;

function strlen() {}
const INI_ALL = 3;
class Exception {}

print \strlen('hi') . "\n"; // global function strlen कल गर्छ
print \INI_ALL . "\n"; // global constant INI_ALL पहुँच गर्छ
$c = new \Exception('error'); // global class Exception को object बनाउँछ
print $c::class . "\n";

   PHP मा namespaces को कार्यान्वयन एक programming language को रूपमा रहेको यसको dynamic
   प्रकृतिबाट प्रभावित छ। त्यसैले, तलको उदाहरण जस्तो code लाई namespaced code मा रूपान्तरण गर्न:

    Elements लाई dynamically पहुँच गर्ने तरिका
    example1.php:


<?php
class classname
{
    function __construct()
    {
        echo __METHOD__,"\n";
    }
}
function funcname()
{
    echo __FUNCTION__,"\n";
}
const constname = "global";

$a = 'classname';
$obj = new $a; // classname::__construct प्रिन्ट गर्छ
$b = 'funcname';
$b(); // funcname प्रिन्ट गर्छ
echo constant('constname'), "\n"; // global प्रिन्ट गर्छ



   यसमा fully qualified name (namespace prefix सहितको class को नाम) प्रयोग गर्नैपर्छ।
   ध्यान दिनुहोस् कि dynamic class name, function name वा constant name भित्र qualified र
   fully qualified नामबीच कुनै भिन्नता नहुने भएकाले सुरुमा backslash राखिरहनु आवश्यक पर्दैन।

    Namespaced elements लाई dynamically पहुँच गर्ने तरिका


<?php
namespace namespacename;
class classname
{
    function __construct()
    {
        echo __METHOD__,"\n";
    }
}
function funcname()
{
    echo __FUNCTION__,"\n";
}
const constname = "namespaced";

/* ध्यान दिनुहोस्, double quotes प्रयोग गर्दा "\\namespacename\\classname" लेख्नुपर्छ */
$a = '\namespacename\classname';
$obj = new $a; // namespacename\classname::__construct प्रिन्ट गर्छ
$a = 'namespacename\classname';
$obj = new $a; // यसले पनि namespacename\classname::__construct प्रिन्ट गर्छ
$b = 'namespacename\funcname';
$b(); // namespacename\funcname प्रिन्ट गर्छ
$b = '\namespacename\funcname';
$b(); // यसले पनि namespacename\funcname प्रिन्ट गर्छ
echo constant('\namespacename\constname'), "\n"; // namespaced प्रिन्ट गर्छ
echo constant('namespacename\constname'), "\n"; // यसले पनि namespaced प्रिन्ट गर्छ

   __NAMESPACE__ को मान एउटा string हुन्छ जसमा हालको namespace को नाम
   रहन्छ। Global, un-namespaced code मा यसमा खाली string रहन्छ।

    __NAMESPACE__ उदाहरण, namespaced code


<?php
namespace MyProject;

echo '"', __NAMESPACE__, '"'; // "MyProject" आउटपुट दिन्छ




    __NAMESPACE__ उदाहरण, global code


<?php
echo '"', __NAMESPACE__, '"'; // "" आउटपुट दिन्छ



   Dynamically नामहरू निर्माण गर्न __NAMESPACE__ constant उपयोगी हुन्छ,
   उदाहरणका लागि:

    Dynamic नाम निर्माणका लागि __NAMESPACE__ को प्रयोग


<?php
namespace MyProject;

function get($classname)
{
    $a = __NAMESPACE__ . '\\' . $classname;
    return new $a;
}

   Aliasing को काम use operator बाट गरिन्छ।
   यहाँ सबै ५ प्रकारका importing देखाउने एउटा उदाहरण दिइएको छ:

    use operator प्रयोग गरेर importing/aliasing गर्ने उदाहरण


<?php
namespace foo;
use My\Full\Classname as Another;

// यो use My\Full\NSname as NSname जस्तै हो
use My\Full\NSname;

// Global class import गर्दै
use ArrayObject;

// Function import गर्दै
use function My\Full\functionName;

// Function लाई alias गर्दै
use function My\Full\functionName as func;

// Constant import गर्दै
use const My\Full\CONSTANT;

$obj = new namespace\Another; // class foo\Another को object बनाउँछ
$obj = new Another; // class My\Full\Classname को object बनाउँछ
NSname\subns\func(); // function My\Full\NSname\subns\func कल गर्छ
$a = new ArrayObject(array(1)); // class ArrayObject को object बनाउँछ
// "use ArrayObject" नराखेको भए class foo\ArrayObject को object बन्ने थियो
func(); // function My\Full\functionName कल गर्छ
echo CONSTANT; // My\Full\CONSTANT को मान प्रिन्ट गर्छ



   ध्यान दिनुहोस् कि namespaced नामहरूका लागि (FooBar जस्ता global नामहरू
   भन्दा फरक, Foo\Bar जस्ता namespace separator भएका fully qualified
   namespace नामहरूमा) सुरुमा backslash राख्नु आवश्यक हुँदैन र त्यसो गर्न सिफारिस पनि गरिँदैन,
   किनकि import नामहरू स्वतः fully qualified नै हुनुपर्छ र यिनलाई हालको namespace को सापेक्ष
   (relative) रूपमा प्रशोधन गरिँदैन।

   कुनै namespace परिभाषा नभएको अवस्थामा, PHP मा namespaces समर्थित हुनुअघि जस्तै सबै class र
   function का परिभाषाहरू global space मा रहन्छन्। कुनै नामको अगाडि \ उपसर्ग
   (prefix) राख्नाले namespace भित्रकै सन्दर्भमा पनि उक्त नाम global space बाट लिइनुपर्ने कुरा
   निर्दिष्ट गर्छ।

    Global space निर्दिष्टीकरणको प्रयोग


<?php
namespace A\B\C;

/* यो function A\B\C\fopen हो */
function fopen() {
     /* ... */
     $f = \fopen(...); // global fopen कल गर्छ
     return $f;
}

   Namespace भित्र PHP ले class name, function वा constant को सन्दर्भमा कुनै unqualified नाम
   भेट्दा, त्यसलाई फरक-फरक प्राथमिकताका साथ resolve गर्छ। Class का नामहरू सधैँ हालको namespace
   को नाममा resolve हुन्छन्। त्यसैले internal वा non-namespaced user classes पहुँच गर्नका लागि
   तिनको fully qualified नाम यसरी उल्लेख गर्नुपर्छ:

    Namespace भित्र global classes पहुँच गर्ने तरिका


<?php
namespace A\B\C;
class Exception extends \Exception {}

$a = new Exception('hi'); // $a चाहिँ class A\B\C\Exception को object हो
var_dump($a::class);
$b = new \Exception('hi'); // $b चाहिँ class Exception को object हो
var_dump($b::class);

$c = new ArrayObject; // fatal error, class A\B\C\ArrayObject फेला परेन

   Functions र constants का लागि भने, यदि namespaced function वा constant अस्तित्वमा छैन भने
   PHP ले global functions वा constants मा fallback गर्छ।

    Namespace भित्र global functions/constants मा fallback


<?php
namespace A\B\C;

const E_ERROR = 45;
function strlen($str)
{
    return \strlen($str) - 1;
}

echo E_ERROR, "\n"; // "45" प्रिन्ट गर्छ
echo INI_ALL, "\n"; // "7" प्रिन्ट गर्छ - global INI_ALL मा fallback हुन्छ

echo strlen('hi'), "\n"; // "1" प्रिन्ट गर्छ
if (is_array('hi')) { // "is not array" प्रिन्ट गर्छ
    echo "is array\n";
} else {
    echo "is not array\n";
}

sect2.para:
    तलका script संयोजनहरू मान्य छन्:

     file1.php


<?php
namespace my\stuff;
class MyClass {}


     another.php


<?php
namespace another;
class thing {}


     file2.php


<?php
namespace my\stuff;
include 'file1.php';
include 'another.php';

use another\thing as MyClass;
$a = new MyClass; // namespace another बाट class "thing" को object बनाउँछ

    my\stuff namespace भित्र MyClass class अवस्थित भए
    तापनि नाममा कुनै conflict हुँदैन, किनकि MyClass को परिभाषा छुट्टै file मा छ। तर, अर्को
    उदाहरणमा भने use statement भएकै file मा MyClass परिभाषित गरिएको हुनाले नाम conflict भई
    fatal error आउँछ।



<?php
namespace my\stuff;
use another\thing as MyClass;
class MyClass {} // fatal error: MyClass चाहिँ import statement सँग बाझिन्छ
$a = new MyClass;

    PHP ले namespaces भित्र अर्को namespace राख्ने (nesting) अनुमति दिँदैन



<?php
namespace my\stuff {
    namespace nested {
        class foo {}
    }
}



    यद्यपि, यसरी nested namespaces को नक्कल (simulate) गर्न सजिलो छ:



<?php
namespace my\stuff\nested {
    class foo {}
}

यो कुरा बुझ्नु अत्यन्त महत्वपूर्ण छ कि backslash लाई strings भित्र escape character को रूपमा प्रयोग गरिने भएकाले, string भित्र प्रयोग गर्दा यसलाई सधैँ दोहोरो (double) लेख्नुपर्छ। अन्यथा अनपेक्षित परिणाम आउने जोखिम रहन्छ:
Double-quoted string भित्र namespaced नामहरू प्रयोग गर्दा हुने जोखिम
<?php $a = "dangerous\name"; // double quoted strings भित्र \n ले newline जनाउँछ! $obj = new $a;
$a = 'not\at\all\dangerous'; // यहाँ कुनै समस्या छैन। $obj = new $a;
Single-quoted string भित्र backslash escape sequence प्रयोग गर्नु धेरै सुरक्षित हुन्छ, तर उत्तम अभ्यासका रूपमा सबै strings मा backslashes लाई escape गर्नु नै राम्रो मानिन्छ।

    कुनै विशेष, built-in constant लाई namespaced constant का रूपमा परिभाषित गर्ने कुनै पनि
    प्रयासले fatal error निम्त्याउँछ

     Undefined constants


<?php
namespace bar;
const NULL = 0; // fatal error;
const true = 'stupid'; // यो पनि fatal error;
// आदि।
